// PipelineK Studio VS Code extension — S5 E5.3 + R5 EVO-C.0+.7
//
// The extension uses the generated sdk.ts (NOT bundled; the operator
// runs `studio generate-sdk-ts --to src/sdk.ts` to keep it in sync).
// The import path "import { StudioClient } from './sdk'" resolves via
// tsconfig at build time; for dev with `tsc -watch`, the file is
// regenerated by the CLI.

import * as vscode from "vscode";
import { StudioClient } from "./sdk";
import { fetchWithTimeout, resolveTimeoutMs } from "./config";
import { SseClient, type SseState, type TreeEvent } from "./sseClient";

interface StudioConfig {
  baseUrl: string;
}

function readConfig(): StudioConfig {
  // Audit F-P1-VSCODE-1 (2026-10-10): the default flipped from
  // http://127.0.0.1:7777 to https://127.0.0.1:7778 to match the
  // studio's post-C-1 HTTPS default. A vscode extension that
  // defaults to plaintext was a silent-downgrade path: an operator
  // who started the studio with --insecure-http would have a
  // working extension over plaintext, defeating the C-1
  // hardening. package.json contributes the new default; this
  // helper is the canonical read site.
  const cfg = vscode.workspace.getConfiguration("pipelinekStudio");
  return { baseUrl: cfg.get<string>("baseUrl") ?? "https://127.0.0.1:7778" };
}

function client(): StudioClient {
  return new StudioClient({ baseUrl: readConfig().baseUrl });
}

/**
 * R5 EVO-C.7 (2026-10-11): render a short label for the
 * status bar based on the SSE state machine. The mapping is
 * intentionally coarse: 4 icon-glyphs cover the 4 states so
 * the operator gets a stable visual signal.
 */
function statusBarLabel(s: SseState): string {
  switch (s.kind) {
    case "connecting":
      return "$(sync~spin) Studio: connecting";
    case "open":
      return "$(check) Studio: live";
    case "backoff":
      return `$(sync) Studio: retry in ${Math.round(s.nextAttemptInMs / 1000)}s`;
    case "closed":
      return "$(warning) Studio: offline";
  }
}

export function activate(context: vscode.ExtensionContext): void {
  const timeoutMs = resolveTimeoutMs();
  // R5 EVO-C.7: the SSE client is the live channel for the
  // sidebar tree (EVO-C.2) and the status bar (EVO-C.1). The
  // client is started eagerly on activate so the operator
  // sees the connection state without invoking a command
  // first. The client is dispos-able, so deactivate releases
  // the EventSource and stops the backoff timer.
  const log = vscode.window.createOutputChannel("PipelineK Studio");
  const sse = new SseClient({ baseUrl: readConfig().baseUrl });
  const statusBar = vscode.window.createStatusBarItem(vscode.StatusBarAlignment.Left, 100);
  statusBar.command = "pipelinek-studio.status";
  statusBar.text = statusBarLabel({ kind: "connecting" });
  statusBar.tooltip = "PipelineK Studio event stream";
  statusBar.show();
  sse.onState((s) => {
    statusBar.text = statusBarLabel(s);
  });
  sse.onEvent((ev: TreeEvent) => {
    // R5 EVO-C.2 (sidebar tree) and EVO-C.1 (status bar
    // counters) will subscribe here. For now we just log to
    // the extension's output channel so the operator can
    // verify the wire format end-to-end.
    log.appendLine(`tree event: ${ev.kind} seq=${ev.seq}`);
  });
  sse.start();
  context.subscriptions.push(
    sse,
    log,
    statusBar,
    vscode.commands.registerCommand("pipelinek-studio.status", () => {
      const snap = sse.snapshot();
      vscode.window.showInformationMessage(
        `PipelineK Studio SSE: ${snap.open ? "open" : "closed"}, lastEventId=${snap.lastEventId ?? "none"}, attempt=${snap.attempt}`,
      );
    }),
    vscode.commands.registerCommand("pipelinek-studio.health", async () => {
      try {
        const res = await fetchWithTimeout(
          `${readConfig().baseUrl}/health`,
          {},
          timeoutMs,
        );
        const text = await res.text();
        vscode.window.showInformationMessage(`PipelineK Studio /health -> ${text}`);
      } catch (e) {
        vscode.window.showErrorMessage(`Studio unreachable: ${(e as Error).message}`);
      }
    }),

    vscode.commands.registerCommand("pipelinek-studio.createExperiment", async () => {
      const name = await vscode.window.showInputBox({
        prompt: "Experiment name",
        placeHolder: "e.g. nightly-cache-bench",
      });
      if (!name) return;
      try {
        const result = (await client().postExperiments({ name })) as { experiment_id?: string; name?: string };
        vscode.window.showInformationMessage(
          `Created experiment ${result.experiment_id ?? "(unknown id)"}: ${result.name ?? name}`,
        );
      } catch (e) {
        vscode.window.showErrorMessage(`Create experiment failed: ${(e as Error).message}`);
      }
    }),

    vscode.commands.registerCommand("pipelinek-studio.listSteps", async () => {
      try {
        const result = (await client().getSteps()) as { steps?: Array<{ id: string; name?: string }> };
        const steps = result.steps ?? [];
        if (steps.length === 0) {
          vscode.window.showInformationMessage("No steps admitted by the Studio.");
          return;
        }
        const picked = await vscode.window.showQuickPick(
          steps.map((s) => ({ label: s.id, description: s.name ?? "" })),
          { placeHolder: `${steps.length} steps admitted by the Studio` },
        );
        if (picked) {
          vscode.window.showInformationMessage(`Selected step: ${picked.label}`);
        }
      } catch (e) {
        vscode.window.showErrorMessage(`List steps failed: ${(e as Error).message}`);
      }
    }),

    vscode.commands.registerCommand("pipelinek-studio.openOpenApi", async () => {
      try {
        const res = await fetchWithTimeout(
          `${readConfig().baseUrl}/openapi.json`,
          {},
          timeoutMs,
        );
        const text = await res.text();
        const doc = await vscode.workspace.openTextDocument({
          content: text,
          language: "json",
        });
        await vscode.window.showTextDocument(doc, { preview: true });
      } catch (e) {
        vscode.window.showErrorMessage(`OpenAPI fetch failed: ${(e as Error).message}`);
      }
    }),
  );
}

export function deactivate(): void {
  // The SSE client and status bar are disposables registered
  // with the extension context, so VS Code disposes them on
  // deactivation. No explicit teardown needed here.
}
